function createInMemoryOrderRepository() {
  const rows = new Map();
  return {
    save(order) {
      rows.set(order.id, { id: order.id, lines: order.lines.map((l) => ({ ...l })) });
    },
    findById(id) {
      return rows.get(id) ?? null;
    },
  };
}

