items.solution:
function saveOrder(adapter, order) {
  try {
    adapter.save(order);
  } catch (err) {
    if (err && err.code === '23505') {
      throw new Error('duplicate order id');
    }
    throw err;
  }
}

function findOrderSafely(adapter, id) {
  try {
    return adapter.findById(id);
  } catch {
    return null;
  }
}
